std::shared_ptr<const AnimationRig> AnimationRig::Load(UUID model){auto asset=AssetManager::GetAsset(model);if(!asset||asset->State!=AssetState::Ready)throw std::invalid_argument("Animation model is not ready");auto description=AssetManager::LoadModel(model);if(!description)throw std::invalid_argument("Animation requires a glTF/GLB model");struct Cached {std::filesystem::path Path;std::filesystem::file_time_type Time;std::weak_ptr<const AnimationRig> Rig;};static std::map<UUID,Cached> cache;auto stamp=std::filesystem::last_write_time(asset->CachePath);if(auto it=cache.find(model);it!=cache.end()&&it->second.Path==asset->CachePath&&it->second.Time==stamp)if(auto rig=it->second.Rig.lock())return rig;
 auto rig=std::make_shared<AnimationRig>();rig->Rig.Bones.resize(description->Nodes.size());for(unsigned i=0;i<description->Nodes.size();++i){auto& n=description->Nodes[i];auto& b=rig->Rig.Bones[i];b.Name=n.Name;b.SourceIndex=n.SourceIndex;b.BindPose={n.Position,n.Rotation,n.Scale};for(auto child:n.Children){if(child>=rig->Rig.Bones.size())throw std::invalid_argument("Invalid animation skeleton");rig->Rig.Bones[child].Parent=int(i);}}if(!rig->Rig.IsValid())throw std::invalid_argument("Invalid animation skeleton");Document doc(asset->CachePath);auto root=doc.Tree.crootref();std::set<std::string> names;std::size_t totalKeys=0;if(root.has_child("animations")){if(root["animations"].num_children()>1024)throw std::invalid_argument("Too many animation clips");for(auto animation:root["animations"].children()){AnimationClip clip;clip.Name=String(animation,"name","Animation "+std::to_string(rig->Clips.size()));auto originalName=clip.Name;unsigned suffix=1;while(names.contains(clip.Name))clip.Name=originalName+"#"+std::to_string(suffix++);names.insert(clip.Name);if(!animation.has_child("channels")||!animation.has_child("samplers"))throw std::invalid_argument("Invalid animation channels");for(auto channel:animation["channels"].children()){auto target=channel["target"];auto path=Text(target["path"]);if(path=="weights")continue;AnimationTrack track;track.Bone=Index(target["node"]);if(path=="translation")track.Channel=AnimationChannel::Position;else if(path=="rotation")track.Channel=AnimationChannel::Rotation;else if(path=="scale")track.Channel=AnimationChannel::Scale;else throw std::invalid_argument("Unsupported animation channel");auto si=Index(channel["sampler"]);if(si>=animation["samplers"].num_children())throw std::invalid_argument("Missing animation sampler");auto sampler=animation["samplers"][si];auto interpolation=String(sampler,"interpolation","LINEAR");if(interpolation=="STEP")track.Interpolation=AnimationInterpolation::Step;else if(interpolation=="CUBICSPLINE")track.Interpolation=AnimationInterpolation::CubicSpline;else if(interpolation!="LINEAR")throw std::invalid_argument("Unknown animation interpolation");auto times=doc.Accessor(Index(sampler["input"]),1),values=doc.Accessor(Index(sampler["output"]),path=="rotation"?4:3);unsigned stride=track.Interpolation==AnimationInterpolation::CubicSpline?3:1;if(values.size()!=times.size()*stride||(totalKeys+=times.size())>2000000)throw std::invalid_argument("Animation key budget/size mismatch");for(std::size_t i=0;i<times.size();++i){AnimationKey key;key.Time=times[i].X;key.Value=values[i*stride+(stride==3?1:0)];if(stride==3){key.InTangent=values[i*stride];key.OutTangent=values[i*stride+2];}track.Keys.push_back(key);clip.Duration=std::max(clip.Duration,key.Time);}clip.Tracks.push_back(std::move(track));}if(!clip.IsValid(rig->Rig))throw std::invalid_argument("Invalid animation clip: "+clip.Name);rig->Clips.push_back(std::move(clip));}}
 if(cache.size()>128)std::erase_if(cache,[](const auto& row){return row.second.Rig.expired();});cache[model]={asset->CachePath,stamp,rig};return rig;
}
bool AnimationController::IsValid()const{if(!std::isfinite(TranslationScale)||TranslationScale<=0||TranslationScale>1000||RetargetMap.size()>4096||States.empty()||States.size()>256||Transitions.size()>1024)return false;std::set<std::string> names;for(auto& s:States){if(s.Name.empty()||s.Name.size()>128||!names.insert(s.Name).second||unsigned(s.Blend)>2||!std::isfinite(s.Speed)||s.Speed<0||s.Speed>100||s.Samples.size()>64)return false;if(s.Blend!=AnimationBlendType::Clip&&(s.ParameterX.empty()||s.Samples.empty()||(s.Blend==AnimationBlendType::Blend2D&&s.ParameterY.empty())))return false;for(auto& p:s.Samples)if(p.Clip.empty()||!std::isfinite(p.Position.X)||!std::isfinite(p.Position.Y)||!std::isfinite(p.Speed)||p.Speed<0||p.Speed>100)return false;}if(!names.contains(Entry))return false;for(auto& t:Transitions){if((t.From!="*"&&!names.contains(t.From))||!names.contains(t.To)||!std::isfinite(t.Duration)||t.Duration<0||t.Duration>60||!std::isfinite(t.ExitTime)||t.ExitTime< -1||t.ExitTime>1000||t.Conditions.size()>16)return false;for(auto& c:t.Conditions)if(c.Parameter.empty()||unsigned(c.Comparison)>3||!std::isfinite(c.Value))return false;}return true;}
AnimationController AnimationController::FromSource(const std::string& source){if(source.size()>1024*1024)throw std::invalid_argument("Animation controller exceeds 1 MiB");auto tree=ryml::parse_in_arena({source.data(),source.size()});auto root=tree.crootref();if(!root.has_child("version")||Index(root["version"])!=1||!root.has_child("states")||!root["states"].is_seq())throw std::invalid_argument("Invalid animation controller document");AnimationController out;out.Entry=String(root,"entry");if(root.has_child("sourceModel")&&!UUID::TryParse(Text(root["sourceModel"]),out.SourceModel))throw std::invalid_argument("Invalid retarget source UUID");out.TranslationScale=Value(root,"translationScale",1);if(root.has_child("retarget"))for(auto row:root["retarget"].children())out.RetargetMap.push_back({Index(row["source"]),Index(row["target"]),Boolean(row,"copyTranslation",false)});for(auto node:root["states"].children()){AnimationState s;s.Name=String(node,"name");s.Clip=String(node,"clip");s.ParameterX=String(node,"parameterX");s.ParameterY=String(node,"parameterY");s.Blend=AnimationBlendType(node.has_child("blend")?Index(node["blend"]):0);s.Loop=Boolean(node,"loop",true);s.Speed=Value(node,"speed",1);if(node.has_child("samples"))for(auto row:node["samples"].children())s.Samples.push_back({String(row,"clip"),{Value(row,"x",0),Value(row,"y",0)},Value(row,"speed",1)});out.States.push_back(std::move(s));}if(root.has_child("transitions"))for(auto node:root["transitions"].children()){AnimationTransition t;t.From=String(node,"from");t.To=String(node,"to");t.Duration=Value(node,"duration",.2f);t.ExitTime=Value(node,"exitTime",-1);if(node.has_child("conditions"))for(auto row:node["conditions"].children())t.Conditions.push_back({String(row,"parameter"),AnimationComparison(row.has_child("comparison")?Index(row["comparison"]):0),Value(row,"value",0)});out.Transitions.push_back(std::move(t));}if(!out.IsValid())throw std::invalid_argument("Invalid animation controller");return out;}
AnimationController AnimationController::Load(UUID id){auto asset=AssetManager::GetAsset(id);if(!asset||asset->State!=AssetState::Ready||asset->SourcePath.extension()!=".banim")throw std::invalid_argument("Animation controller is not ready");auto bytes=Read(asset->CachePath);return FromSource({reinterpret_cast<const char*>(bytes.data()),bytes.size()});}
